define(["jquery","core/modal_factory"],function(a,b){var c=a("#know_more_templates");b.create({title:"<b>Steps to create a template</b>",body:"<p>1. Go to \u2018Course catalogue\u2019 from  left side navigation</br>\n2. Click on \u2018Manage courses\u2019 Button</br>\n3. In \u2018Course and category management\u2019 select a catagory to view courses</br>\n4. Select checkbox next to course you want to move</br>\n5. Select \u2018Course templates\u2019 from the dropdown of \u2018Move selected courses to...\u2019</br>\n6. Click Move.</br></br>\nCongratulations! Your newly created course can now be used as a template.</p>"},c).done(function(a){})})
